import 'package:flutter/material.dart';import 'package:supabase_flutter/supabase_flutter.dart';
class LoginPage extends StatefulWidget{const LoginPage({super.key});@override State<LoginPage> createState()=>_S();}
class _S extends State<LoginPage>{final e=TextEditingController(),p=TextEditingController();bool busy=false,hide=true;Future<void> go()async{setState(()=>busy=true);try{await Supabase.instance.client.auth.signInWithPassword(email:e.text.trim(),password:p.text);}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Giriş yapılamadı: $x')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:560),child:Card(child:Padding(padding:const EdgeInsets.all(36),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('Giriş Yap',style:TextStyle(fontSize:38,fontWeight:FontWeight.w900)),const SizedBox(height:24),TextField(controller:e,decoration:const InputDecoration(labelText:'E-posta')),const SizedBox(height:14),TextField(controller:p,obscureText:hide,onSubmitted:(_)=>go(),decoration:InputDecoration(labelText:'Şifre',suffixIcon:IconButton(onPressed:()=>setState(()=>hide=!hide),icon:Icon(hide?Icons.visibility_off:Icons.visibility)))),const SizedBox(height:20),FilledButton(onPressed:busy?null:go,child:Padding(padding:const EdgeInsets.all(14),child:Text(busy?'Bekleyin...':'Giriş Yap')))]))))));}
